@once
<style>
.rt-regions{--regions-bg:#fff;--regions-muted-bg:#f6f8fb;--regions-text:#17283f;--regions-muted:#697c97;--regions-border:#dce4ee;--regions-preferred:#087f62;--regions-possible:#b65b0b;--regions-emergency:#8551ba;overflow:hidden;border:1px solid var(--regions-border);border-radius:20px;background:var(--regions-bg);color:var(--regions-text)}
.dark .rt-regions{--regions-bg:#162235;--regions-muted-bg:#1c2b40;--regions-text:#e8edf5;--regions-muted:#a7b5ca;--regions-border:#35465e;--regions-preferred:#47d7b0;--regions-possible:#ffb06a;--regions-emergency:#c7a0ed}
.rt-regions [data-zone=preferred]{--zone:var(--regions-preferred);--zone-fill:rgba(8,127,98,.13)}.rt-regions [data-zone=possible]{--zone:var(--regions-possible);--zone-fill:rgba(230,132,42,.15)}.rt-regions [data-zone=emergency]{--zone:var(--regions-emergency);--zone-fill:rgba(133,81,186,.13)}
.rt-regions__header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 28px;border-bottom:1px solid var(--regions-border)}.rt-regions h2{margin:0;font-size:20px;line-height:1.4;font-weight:650;letter-spacing:-.025em}.rt-regions__header p{margin:5px 0 0;font-size:12px;color:var(--regions-muted);line-height:1.6}
.rt-regions__layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,1fr)}.rt-regions__visual{position:relative;min-width:0;padding:22px 28px;background:var(--regions-muted-bg);border-right:1px solid var(--regions-border)}.rt-regions__map-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;font-weight:600}.rt-regions__map-heading span:last-child{font-size:11px;color:var(--regions-muted);font-weight:400}.rt-regions .rt-regions__map{height:510px;max-height:none;width:100%;margin:14px auto;--rt-map-accent:#6a7d98}.rt-regions__overlay{position:absolute;inset:0;width:100%;height:100%;overflow:hidden}.rt-regions__state{fill:var(--zone-fill,transparent);stroke:var(--zone,transparent);stroke-width:2;cursor:pointer;transition:fill .15s ease,stroke .15s ease}.rt-regions__state:hover,.rt-regions__state:focus-visible{fill:var(--zone-fill,#c9d5e5);stroke:var(--regions-text);stroke-width:4;outline:none}.rt-regions__radii{pointer-events:none}.rt-regions__radii path{fill:var(--zone-fill);stroke:var(--zone);stroke-width:3;stroke-dasharray:9 7}.rt-regions__origin{fill:var(--regions-text);stroke:var(--regions-bg);stroke-width:5}

.rt-regions__editor{min-width:0;padding:24px;display:flex;flex-direction:column;gap:24px}.rt-regions__zones{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.rt-regions__zones button{min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:6px;border:1px solid var(--regions-border);border-radius:12px;padding:12px;color:var(--regions-muted);text-align:left;transition:background .15s ease,border-color .15s ease}.rt-regions__zones button span{font-size:12px;font-weight:600}.rt-regions__zones button small{font-size:10px}.rt-regions__zones button[aria-pressed=true]{background:var(--zone-fill);border-color:var(--zone);color:var(--zone)}
.rt-regions fieldset{min-width:0}.rt-regions legend{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;margin:0 0 12px;font-size:12px;font-weight:600}.rt-regions legend>span{font-size:10px;color:var(--regions-muted);font-weight:400}.rt-regions input[type=text],.rt-regions input[type=number]{display:block;width:100%;min-width:0;min-height:42px;border:1px solid var(--regions-border);border-radius:8px;background:var(--regions-bg);color:var(--regions-text);font:inherit;font-size:12px;padding:9px 11px;box-shadow:none}.rt-regions input::placeholder{color:var(--regions-muted)}.rt-regions__radius-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:12px}.rt-regions__radius-fields label>span:first-child{display:block;font-size:10px;margin-bottom:6px;color:var(--zone);font-weight:600}.rt-regions__unit{position:relative;display:block}.rt-regions__unit>span{position:absolute;right:10px;top:50%;transform:translateY(-50%);font-size:10px;color:var(--regions-muted);pointer-events:none}.rt-regions__unit input[type=number]{padding-right:31px;appearance:textfield}.rt-regions__unit input::-webkit-inner-spin-button{display:none}.rt-regions__hint{font-size:10px;color:var(--regions-muted);line-height:1.6;margin:10px 0 0}
.rt-regions__state-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}.rt-regions__state-list button{display:flex;align-items:center;gap:7px;text-align:left;font-size:10px;line-height:1.3;min-height:36px;border:1px solid transparent;border-radius:7px;padding:7px;color:var(--zone,var(--regions-muted));background:var(--zone-fill,transparent)}.rt-regions__state-list button i{font-size:10px;flex:0 0 12px}.rt-regions__state-list button:hover{border-color:var(--zone,var(--regions-border))}.rt-regions__state-list button span{overflow-wrap:anywhere}
.rt-regions__exclusions{border-top:1px solid var(--regions-border);padding-top:15px}.rt-regions__exclusions summary{font-size:12px;cursor:pointer;min-height:28px}.rt-regions__exclusions summary>span{color:var(--regions-muted);margin-left:8px}.rt-regions__exclusion{display:grid;grid-template-columns:minmax(0,1fr) 75px 32px;align-items:center;gap:7px;margin-top:10px}.rt-regions__exclusion button{min-height:38px;color:var(--regions-muted)}.rt-regions__text-button{font-size:11px;color:var(--regions-text);display:inline-flex;align-items:center;gap:7px;min-height:36px;margin-top:9px}
.rt-regions__footer{border-top:1px solid var(--regions-border);display:flex;align-items:center;justify-content:space-between;gap:22px;padding:18px 24px}.rt-regions__feedback{font-size:11px;line-height:1.6;color:var(--regions-muted);max-width:520px}.rt-regions__actions{display:flex;gap:8px;flex-shrink:0}.rt-regions__actions button{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:40px;border-radius:9px;padding:10px 16px;font-size:12px;font-weight:600}.rt-regions__save{background:#e90039;color:white}.rt-regions__save:hover{background:#c80031}.rt-regions__reset{background:var(--regions-muted-bg);color:var(--regions-muted)}.rt-regions__invalid{color:#b42332;font-size:11px;line-height:1.5;margin-top:8px}.rt-regions__success{color:var(--regions-preferred)}.rt-regions__message{padding:24px}.rt-regions button:focus-visible,.rt-regions input:focus-visible,.rt-regions summary:focus-visible{outline:2px solid var(--regions-text);outline-offset:3px}.rt-regions button:disabled{opacity:.55;cursor:wait}
@media(max-width:900px){.rt-regions__layout{grid-template-columns:minmax(0,.95fr) minmax(320px,1fr)}.rt-regions__visual{padding:20px 15px}.rt-regions .rt-regions__map{height:450px}.rt-regions__editor{padding:20px 16px}.rt-regions__zones button{padding:10px 8px}}
@media(max-width:700px){.rt-regions__header{padding:20px;align-items:flex-start;flex-direction:column;gap:14px}.rt-regions__layout{grid-template-columns:minmax(0,1fr)}.rt-regions__visual{border-right:0;border-bottom:1px solid var(--regions-border);padding:18px 20px}.rt-regions .rt-regions__map{height:340px;margin:12px auto}.rt-regions__editor{padding:20px;gap:22px}.rt-regions__state-list button{font-size:11px;min-height:40px}.rt-regions__footer{padding:18px 20px;align-items:stretch;flex-direction:column;gap:12px}.rt-regions__actions{justify-content:flex-end}.rt-regions__actions button{flex:1}.rt-regions__feedback{font-size:10px}}
@media(prefers-reduced-motion:reduce){.rt-regions *{transition:none!important}}
</style>
@endonce
